from collections import Counter

def transform(grid):
    n, m = len(grid), len(grid[0])
    h, w = n // 3, m // 3
    out = []
    for br in range(h):
        row = []
        for bc in range(w):
            cells = [
                grid[r][c]
                for r in range(br * 3, br * 3 + 3)
                for c in range(bc * 3, bc * 3 + 3)
                if grid[r][c] != 5
            ]
            row.append(Counter(cells).most_common(1)[0][0] if cells else 5)
        out.append(row)
    return out
